              display: flex;
              justify-content: space-between;
              align-items: center;
            }

            .drawer-title {
              font-size: 20px;
              font-weight: bold;
              margin: 0;
            }

            .drawer-close-btn {
              background: none;
              border: none;
              font-size: 24px;
              cursor: pointer;
              padding: 0;
              width: 32px;
              height: 32px;
              display: flex;
              align-items: center;
              justify-content: center;
            }

            .drawer-close-btn:hover {
              background-color: #f0f0f0;
              border-radius: 4px;
            }

            .drawer-content {
              padding: 20px;
              overflow-y: auto;
              flex: 1;
            }

            .drawer-footer {
              padding: 20px;
