              border-color: #007bff;
            }

            button.primary:hover {
              background-color: #0056b3;
            }

            button.secondary {
              background-color: white;
              color: #333;
            }

            button.secondary:hover {
              background-color: #f0f0f0;
            }

            .main-content {
              max-width: 800px;
            }
          </style>
        </head>
        <body>
          <div class="main-content">
            <h1>Main Page Content</h1>
            <p>This is the main page content. Click the button below to open the drawer.</p>
            <button id="open-drawer-btn" class="primary">Open Drawer</button>
          </div>

          <div class="drawer-overlay" id="drawer-overlay"></div>

          <div class="drawer" id="drawer" role="dialog" aria-labelledby="drawer-title" aria-modal="true">
            <div class="drawer-header">
              <h2 class="drawer-title" id="drawer-title">Drawer Panel</h2>
              <button class="drawer-close-btn" id="close-drawer-btn" aria-label="Close drawer">×</button>
            </div>
            <div class="drawer-content">
              <p>This is the drawer content. It slides in from the right side of the screen.</p>
              <p>You can add any content here - forms, lists, settings, etc.</p>
              <h3>Features:</h3>
              <ul>
                <li>Smooth slide-in animation from the right</li>
                <li>Semi-transparent overlay backdrop</li>
                <li>Close button in the header</li>
                <li>Click outside to close</li>
                <li>Accessible with proper ARIA attributes</li>
              </ul>
            </div>
            <div class="drawer-footer">
              <button class="secondary" id="cancel-btn">Cancel</button>
              <button class="primary" id="confirm-btn">Confirm</button>
            </div>
          </div>

          <script>
            const drawer = document.getElementById('drawer');
            const overlay = document.getElementById('drawer-overlay');
            const openBtn = document.getElementById('open-drawer-btn');
            const closeBtn = document.getElementById('close-drawer-btn');
            const cancelBtn = document.getElementById('cancel-btn');
            const confirmBtn = document.getElementById('confirm-btn');

            function openDrawer() {
              drawer.classList.add('open');
              overlay.classList.add('open');
              document.body.style.overflow = 'hidden';
            }

            function closeDrawer() {
              drawer.classList.remove('open');
              overlay.classList.remove('open');
              document.body.style.overflow = 'auto';
            }

            openBtn.addEventListener('click', openDrawer);
            closeBtn.addEventListener('click', closeDrawer);
            cancelBtn.addEventListener('click', closeDrawer);
            overlay.addEventListener('click', closeDrawer);

            confirmBtn.addEventListener('click', () => {
              console.log('Confirmed');
              closeDrawer();
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should open drawer from the right when button is clicked', async ({ page }) => {
    const drawer = page.locator('#drawer');

    // Verify drawer is initially hidden (off-screen)
    const initialTransform = await drawer.evaluate(el => 
      window.getComputedStyle(el).transform
    );
    expect(initialTransform).toContain('matrix');

    // Click the open button
    await page.getByRole('button', { name: 'Open Drawer' }).click();

    // Verify drawer is now visible
    await expect(drawer).toHaveClass(/open/);

    // Verify overlay is visible
    const overlay = page.locator('#drawer-overlay');
    await expect(overlay).toHaveClass(/open/);
  });

  test('should close drawer when close button is clicked', async ({ page }) => {
    const drawer = page.locator('#drawer');
    const overlay = page.locator('#drawer-overlay');

    // Open the drawer
    await page.getByRole('button', { name: 'Open Drawer' }).click();
    await expect(drawer).toHaveClass(/open/);

    // Click the close button
    await page.getByLabel('Close drawer').click();

    // Verify drawer is closed
    await expect(drawer).not.toHaveClass(/open/);
    await expect(overlay).not.toHaveClass(/open/);
  });

